def _json_response(text):
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        match = re.search(r"<pre[^>]*>(.*?)</pre>", text, re.I | re.S)
        if not match:
            raise
        return json.loads(html.unescape(match.group(1)))


def _description(value):
    text = value or ""
    text = re.sub(
        r"<\s*(?:br|p|div|li|h[1-6]|tr|section|article|blockquote)[^>]*>",
        "\n",
        text,
        flags=re.I,
    )
    text = re.sub(
        r"</\s*(?:p|div|li|h[1-6]|tr|section|article|blockquote)\s*>",
        "\n",
        text,
        flags=re.I,
    )
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text).replace("\xa0", " ")
    text = re.sub(r"[ \t\r\f\v]+", " ", text)
    text = re.sub(r" *\n *", "\n", text)
    return re.sub(r"\n{3,}", "\n\n", text).strip()


def _location(opening, fallback):
    records = (
        opening.get("atsLocation"),
        opening.get("location"),
        fallback.get("atsLocation"),
        fallback.get("location"),
    )
    for record in records:
        if not record:
            continue
        parts = []
        for key in ("city", "state", "province", "country", "addressCountry"):
            value = record.get(key)
            if value and value not in parts:
                parts.append(value)
        if parts:
            return ", ".join(parts)
    return "Mexico"


def crawl(ctx):
    listing = _json_response(ctx.fetch(SITE))
    roles = listing.get("result", [])

    for role in roles:
        external_id = str(role["id"])
        opening = _SNAPSHOT.get(external_id)

        if not opening:
            detail_url = (
                f"https://konfio.bamboohr.com/careers/{external_id}/detail"
            )
            detail = _json_response(ctx.fetch(detail_url))
            opening = detail.get("result", {}).get("jobOpening", {})

        if opening.get("jobOpeningStatus") != "Open":
            continue

        canonical_url = opening.get("jobOpeningShareUrl")
        if not canonical_url:
            canonical_url = (
                f"https://konfio.bamboohr.com/careers/{external_id}"
            )

        fields = {
            "source": SITE,
            "url": canonical_url,
            "title": opening.get("jobOpeningName")
                or role.get("jobOpeningName"),
            "company": "Konfio",
            "location": _location(opening, role),
            "description": _description(opening.get("description")),
            "external_id": external_id,
            "apply_url": canonical_url,
        }
        optional = {
            "department": opening.get("departmentLabel")
                or role.get("departmentLabel"),
            "employment_type": opening.get("employmentStatusLabel")
                or role.get("employmentStatusLabel"),
            "posted_at": opening.get("datePosted"),
            "salary": opening.get("compensation"),
        }
        fields.update({key: value for key, value in optional.items() if value})
        yield fields
